private void resetInternal(boolean resetRenderers,boolean releaseMediaSource,boolean resetPosition,boolean resetState,boolean resetError){
  handler.removeMessages(MSG_DO_SOME_WORK);
  rebuffering=false;
  mediaClock.stop();
  rendererPositionUs=0;
  for (  Renderer renderer : enabledRenderers) {
    try {
      disableRenderer(renderer);
    }
 catch (    ExoPlaybackException|RuntimeException e) {
      Log.e(TAG,"Disable failed.",e);
    }
  }
  if (resetRenderers) {
    for (    Renderer renderer : renderers) {
      try {
        renderer.reset();
      }
 catch (      RuntimeException e) {
        Log.e(TAG,"Reset failed.",e);
      }
    }
  }
  enabledRenderers=new Renderer[0];
  if (resetPosition) {
    pendingInitialSeekPosition=null;
  }
 else   if (resetState) {
    resetPosition=true;
    if (pendingInitialSeekPosition == null && !playbackInfo.timeline.isEmpty()) {
      playbackInfo.timeline.getPeriodByUid(playbackInfo.periodId.periodUid,period);
      long windowPositionUs=playbackInfo.positionUs + period.getPositionInWindowUs();
      pendingInitialSeekPosition=new SeekPosition(Timeline.EMPTY,period.windowIndex,windowPositionUs);
    }
  }
  try {
    queue.clear(!resetState);
  }
 catch (IllegalStateException e) {
    Log.e(TAG,"Clear queue failed.",e);
  }
  shouldContinueLoading=false;
  if (resetState) {
    queue.setTimeline(Timeline.EMPTY);
    for (    PendingMessageInfo pendingMessageInfo : pendingMessages) {
      pendingMessageInfo.message.markAsProcessed(false);
    }
    pendingMessages.clear();
    nextPendingMessageIndex=0;
  }
  MediaPeriodId mediaPeriodId=resetPosition ? playbackInfo.getDummyFirstMediaPeriodId(shuffleModeEnabled,window,period) : playbackInfo.periodId;
  long startPositionUs=resetPosition ? C.TIME_UNSET : playbackInfo.positionUs;
  long contentPositionUs=resetPosition ? C.TIME_UNSET : playbackInfo.contentPositionUs;
  playbackInfo=new PlaybackInfo(resetState ? Timeline.EMPTY : playbackInfo.timeline,mediaPeriodId,startPositionUs,contentPositionUs,playbackInfo.playbackState,resetError ? null : playbackInfo.playbackError,false,resetState ? TrackGroupArray.EMPTY : playbackInfo.trackGroups,resetState ? emptyTrackSelectorResult : playbackInfo.trackSelectorResult,mediaPeriodId,startPositionUs,0,startPositionUs);
  if (releaseMediaSource) {
    if (mediaSource != null) {
      mediaSource.releaseSource(this);
      mediaSource=null;
    }
  }
}
